'use strict';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',file:'M14 2H5v20h14V7z M14 2v5h5 M8 12h8 M8 16h6',check:'M5 12l4 4L19 6',clock:'M12 8v5l3 2 M22 12a10 10 0 11-20 0 10 10 0 0120 0',upload:'M12 16V3 M7 8l5-5 5 5 M4 15v6h16v-6',users:'M16 21v-3a4 4 0 00-4-4H6a4 4 0 00-4 4v3 M13 7a4 4 0 11-8 0 4 4 0 018 0 M17 4a4 4 0 010 8 M22 21v-3a4 4 0 00-3-4',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',logout:'M9 4H3v16h6 M9 12h12 M17 8l4 4-4 4',menu:'M3 6h18 M3 12h18 M3 18h18',box:'M3 7l9-5 9 5v10l-9 5-9-5z M3 7l9 5 9-5 M12 12v10 M8 4l9 5',calendar:'M4 5h16v16H4z M8 2v6 M16 2v6 M4 11h16',download:'M12 3v13 M7 11l5 5 5-5 M4 17v4h16v-4',edit:'M15 4l5 5 M4 15L17 2l5 5L9 20l-6 1z',back:'M19 12H5 M10 7l-5 5 5 5',x:'M6 6l12 12 M18 6L6 18',shield:'M12 2l9 4v6c0 5-9 10-9 10S3 17 3 12V6z M8 11l3 3 5-6',pin:'M19 9c0 5-7 12-7 12S5 14 5 9a7 7 0 1114 0 M14 9a2 2 0 11-4 0 2 2 0 014 0',warehouse:'M3 10l9-7 9 7v11H3z M7 21V11h10v10 M7 15h10',image:'M3 3h18v18H3z M3 17l5-5 4 4 4-6 5 7 M9 7h.01',search:'M21 21l-5-5 M18 10a8 8 0 11-16 0 8 8 0 0116 0',spark:'M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z'};
const icon=n=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[n]||paths.file}"/></svg>`;
const date=v=>v?new Date(v+'T00:00:00').toLocaleDateString('id-ID',{day:'2-digit',month:'short',year:'numeric'}):'Belum tercatat';
const days=v=>Math.round((new Date(v+'T00:00:00')-new Date(isoDate()+'T00:00:00'))/86400000);
const validDate=s=>/^\d{4}-\d{2}-\d{2}$/.test(s)&&!Number.isNaN(Date.parse(s))&&new Date(s).toISOString().slice(0,10)===s;
const uid=()=>window.crypto?.randomUUID?crypto.randomUUID():'id'+Date.now()+Math.random().toString(36).slice(2);
const get=(table,id)=>db[table].find(x=>x.id===id);
const city=id=>get('cities',id)?.name||'Belum dipetakan';
const type=a=>get('types',a?.typeId)||{name:'Belum tercatat',category:''};
const recordDocs=id=>db.documents.filter(d=>d.recordId===id);
const docStatus=d=>!d.end||d.precision!=='day'?'Belum lengkap':d.start&&d.start>isoDate()?'Belum mulai':days(d.end)<0?'Expired':days(d.end)<=30?'Segera berakhir':d.start?'Aktif':'Awal belum tercatat';
const badge=(text,kind='')=>`<span class="badge ${kind||({'Aktif':'active','Segera berakhir':'expiring-soon','Expired':'expired','Nonaktif':'inactive','Belum lengkap':'unknown','Belum mulai':'unknown','Di gudang':'warehouse-badge'})[text]||'neutral'}">${esc(text)}</span>`;
const link=(text,route,kind='',ico='')=>`<a class="btn ${kind}" href="#/${route}">${ico?icon(ico):''}${esc(text)}</a>`;
const opts=(list,selected='')=>list.map(x=>{const v=typeof x==='string'?x:x.id;const label=typeof x==='string'?x:x.name;return `<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(label)}</option>`;}).join('');
const admin=()=>session?.role==='Admin';
let session=null;try{session=get('users',JSON.parse(sessionStorage.getItem(SESSION_KEY)))||null;if(!session?.active)session=null;}catch(e){}
let charts=[],filters={},page=1,importRows=[],importName='',importMode='skip';
const routeNow=()=>location.hash.replace(/^#\/?/,'').split('/')[0]||'dashboard';
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function heading(title,sub,actions=''){return `<div class="page-heading"><div><h1>${esc(title)}</h1><p>${esc(sub)}</p></div><div class="actions">${actions}</div></div>`;}
const empty=(text='Belum ada data yang sesuai.')=>`<div class="empty">${icon('search')}<h3>${esc(text)}</h3><p>Coba ubah pencarian atau filter Anda.</p></div>`;
function shell(content,route){const groups=[['WORKSPACE',[['dashboard','Overview','grid'],['records','Data Monitoring','file'],['borrowers','Peminjam','users'],['firearms','Senjata / Alat','box'],['documents','Dokumen','file'],['locations','Lokasi & Gudang','warehouse']]],['DATA MANAGEMENT',[...(admin()?[['import','Import Excel','upload']]:[]),['cities','Master Kota','pin'],...(admin()?[['users','Manajemen User','users']]:[])]]];const active=({detail:'records',add:'records',edit:'records',borrower:'borrowers',firearm:'firearms',document:'documents'})[route]||route;return `<aside class="sidebar"><a href="#/dashboard" class="brand"><span class="brandmark">P</span>${APP_NAME}</a><div class="workspace-label">MONITORING WORKSPACE</div>${groups.map(([title,items])=>`<div class="nav-caption">${title}</div><nav>${items.map(([r,t,i])=>`<a class="nav-link ${active===r?'active':''}" href="#/${r}">${icon(i)}${t}</a>`).join('')}</nav>`).join('')}<div class="sidebar-bottom"><div class="status-tag"><strong>${icon('shield')} Data dari sistem eksternal</strong>Workspace pemantauan & arsip.<span class="status-pill">Prototype · Data fiktif</span></div><div class="profile"><span class="avatar">${esc(session.name.split(' ').map(n=>n[0]).slice(0,2).join(''))}</span><div><strong>${esc(session.name)}</strong><small>${admin()?'Administrator':'Viewer'}</small></div><button class="btn ghost logout" data-action="logout" title="Keluar">${icon('logout')}</button></div></div></aside><div class="backdrop" data-action="menu"></div><div class="workspace"><header class="topbar"><div class="actions"><button class="btn ghost mobile-menu" data-action="menu" aria-label="Buka menu">${icon('menu')}</button><div class="top-identity"><span class="mobile-brand">${APP_NAME}</span><span class="breadcrumb">Workspace <span>/</span> <strong>${esc(({dashboard:'Overview',records:'Monitoring',borrowers:'Peminjam',firearms:'Senjata / Alat',documents:'Arsip dokumen',locations:'Lokasi & Gudang',cities:'Master kota',import:'Import Excel',users:'Manajemen user',detail:'Detail monitoring',borrower:'Detail peminjam',firearm:'Detail aset',document:'Detail dokumen',add:'Tambah data',edit:'Edit data'})[route]||'Workspace')}</strong></span></div></div><div class="top-right"><span class="top-date">${icon('calendar')} ${date(isoDate())}</span><span class="role-tag">${admin()?'Admin':'Read only'}</span><span class="avatar">${esc(session.name[0])}</span></div></header><main class="content">${content}<footer class="footer"><span>${APP_NAME} · Monitoring & arsip eksternal</span><span>Prototype · Semua data awal fiktif</span></footer></main></div><nav class="bottom-nav" aria-label="Navigasi utama">${[['dashboard','Overview','grid'],['records','Data','file'],['borrowers','Peminjam','users'],['documents','Dokumen','file']].map(([r,t,i])=>`<a href="#/${r}" class="${active===r?'active':''}">${icon(i)}<span>${t}</span></a>`).join('')}<button data-action="menu">${icon('menu')}<span>Lainnya</span></button></nav>`;}
function login(){return `<main class="login"><section class="login-story"><div class="brand"><span class="brandmark">P</span>${APP_NAME}</div><div><div class="eyebrow">PERMIT DATA MONITORING</div><h1>Data terhubung.<br>Pemantauan lebih jelas.</h1><p>Pantau pemegang izin, identitas alat, dokumen eksternal, dan masa berlaku dalam satu workspace.</p><div class="login-stat"><div><b>01</b><span>Workspace monitoring</span></div><div><b>360°</b><span>Visibilitas data</span></div></div></div><small>Import, organize, stay informed.</small></section><section class="login-form-wrap"><form id="login-form" class="login-form"><div class="equipment-icon">${icon('shield')}</div><h1>Selamat datang kembali.</h1><p>Masuk untuk memantau data perizinan Anda.</p><label for="username">Username</label><input id="username" name="username" autocomplete="username" placeholder="Masukkan username" required><label for="password">Password</label><input id="password" name="password" type="password" autocomplete="current-password" placeholder="Masukkan password" required><div id="login-error" class="error" role="alert"></div><button class="btn primary" type="submit">Masuk ke workspace ${icon('arrow')}</button><div class="credential-box"><strong>Akun contoh</strong><p>admin / admin123 <button type="button" data-action="quick-login" data-role="admin">Admin</button></p><p>user / user123 <button type="button" data-action="quick-login" data-role="user">Viewer</button></p><small>Data fiktif · Tersimpan di browser ini</small></div></form></section></main>`;}
const latestExpiry=r=>recordDocs(r.id).filter(d=>d.end&&d.precision==='day').map(d=>d.end).sort().at(-1)||'';
function dashboard(){const wh=db.assets.filter(a=>get('locations',a.locationId)?.kind==='Gudang').length;const exp=db.documents.filter(d=>docStatus(d)==='Segera berakhir').sort((a,b)=>a.end.localeCompare(b.end));const recent=db.records.slice().sort((a,b)=>b.importedAt.localeCompare(a.importedAt)).slice(0,5);return `${heading('Semua data, dalam satu pandangan.','Pantau dokumen, pemegang izin, dan aset yang tercatat.',admin()?link('Import Excel','import','','upload')+link('Tambah Data','add','primary','plus'):'')}<section class="hero-monitor"><div class="hero-copy"><span class="hero-label">MONITORING OVERVIEW</span><div class="hero-metric"><strong>${db.records.length.toLocaleString('id-ID')}</strong><span>Total data<br>monitoring</span></div><p>Register perizinan dari sistem eksternal.</p><div class="hero-chip">${icon('file')} ${db.documents.length} referensi dokumen terhubung</div></div><div class="hero-plot"><div class="hero-chart-head"><span>Data masuk per bulan</span><span>6 bulan terakhir</span></div><div class="hero-canvas"><canvas id="hero-chart" role="img" aria-label="Jumlah data monitoring masuk enam bulan terakhir"></canvas></div><small>Aktivitas pencatatan data · bukan transaksi peminjaman</small></div></section><div class="monitor-kpis">${[['Total Senjata / Alat',db.assets.length,'box','blue'],['Total Peminjam',db.borrowers.length,'users','purple'],['Dokumen Aktif',db.documents.filter(d=>d.start&&['Aktif','Segera berakhir'].includes(docStatus(d))).length,'shield','green'],['Segera Berakhir',exp.length,'clock','amber'],['Dokumen Expired',db.documents.filter(d=>docStatus(d)==='Expired').length,'calendar','coral'],['Di Gudang',wh,'warehouse','cyan']].map(([t,n,i,c])=>`<div class="metric-card ${c}"><span class="metric-icon">${icon(i)}</span><span class="metric-name">${t}</span><strong>${String(n).padStart(2,'0')}</strong><small>${t==='Segera Berakhir'?'Dalam 30 hari':t==='Di Gudang'?'Lokasi tercatat':t==='Total Peminjam'?`${db.borrowers.filter(b=>b.active).length} berstatus aktif`:'Data workspace'}</small></div>`).join('')}</div><div class="analytics-grid">${[['month-chart','Pencatatan per bulan','Jumlah register yang masuk','bar'],['city-chart','Sebaran kota','Kota pada register monitoring','bar'],['type-chart','Jenis senjata / alat','Komposisi aset tercatat','donut'],['doc-chart','Masa berlaku dokumen','Status berdasarkan tanggal tercatat','donut']].map(([id,title,sub,kind])=>`<section class="panel"><div class="panel-head"><div><h2>${title}</h2><p>${sub}</p></div><span class="small-icon">${icon(kind==='bar'?'grid':'file')}</span></div><div class="mini-chart"><canvas id="${id}" role="img" aria-label="${title}"></canvas></div></section>`).join('')}</div><div class="bottom-grid monitoring-lists"><section class="panel"><div class="panel-head"><div><h2>Segera berakhir</h2><p>Dokumen dalam 30 hari ke depan</p></div><a href="#/documents">Semua dokumen →</a></div>${exp.slice(0,4).map(d=>{const r=get('records',d.recordId);const b=get('borrowers',r?.borrowerId);return `<a class="expiry-item" href="#/document/${d.id}"><span class="equipment-icon orange-text">${icon('clock')}</span><span class="list-copy"><strong>${esc(b?.name||'—')}</strong><small>${esc(d.number)} · ${date(d.end)}</small></span><span class="days">${days(d.end)} hari</span></a>`;}).join('')||empty('Tidak ada dokumen segera berakhir.')}<div class="panel-foot">Tanggal kosong atau parsial ditandai “Belum lengkap”.</div></section><section class="panel"><div class="panel-head"><div><h2>Data terbaru masuk</h2><p>Register dari import & input lokal</p></div><a href="#/records">Lihat semua →</a></div>${recent.map(r=>`<a class="expiry-item" href="#/detail/${r.id}"><span class="equipment-icon">${icon('file')}</span><span class="list-copy"><strong>${esc(get('borrowers',r.borrowerId)?.name)}</strong><small>${esc(r.number)} · ${esc(city(r.cityId))}</small></span><small class="list-date">${date(r.importedAt)}</small></a>`).join('')||empty()}</section></div><section class="panel updates-panel"><div class="panel-head"><div><h2>Pembaruan terakhir</h2><p>Jejak perubahan data monitoring</p></div>${icon('clock')}</div><div class="updates-grid">${db.records.slice().sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)).slice(0,3).map(r=>`<a class="update-item" href="#/detail/${r.id}"><span class="update-dot"></span><div><strong>${esc(r.history.at(-1)?.title||'Data diperbarui')}</strong><p>${esc(r.number)} · ${esc(get('borrowers',r.borrowerId)?.name)}</p><small>${date(r.updatedAt)}</small></div></a>`).join('')}</div></section>`;}
function drawCharts(){const months=Array.from({length:6},(_,i)=>{const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-5+i);return localDay(d).slice(0,7);});const labels=months.map(m=>new Date(m+'-01T00:00:00').toLocaleDateString('id-ID',{month:'short'}));const values=months.map(m=>db.records.filter(r=>r.importedAt.startsWith(m)).length);const cityLabels=[...db.cities.map(c=>c.name),'Belum dipetakan'];const cityValues=[...db.cities.map(c=>db.records.filter(r=>r.cityId===c.id).length),db.records.filter(r=>!r.cityId).length];const typeNames=[...new Set(db.assets.map(a=>type(a).name))];const states=['Aktif','Segera berakhir','Expired','Belum lengkap','Belum mulai','Awal belum tercatat'];const colors=['#54b49b','#efba62','#df858b','#a5b6cf','#8398e1','#72bbce'];const configs=[['hero-chart',labels,values,'line'],['month-chart',labels,values,'bar'],['city-chart',cityLabels,cityValues,'bar'],['type-chart',typeNames,typeNames.map(n=>db.assets.filter(a=>type(a).name===n).length),'doughnut'],['doc-chart',states,states.map(s=>db.documents.filter(d=>docStatus(d)===s).length),'doughnut']];if(!window.Chart){configs.forEach(([id,ls,vs])=>{$('#'+id).parentElement.innerHTML=`<div class="chart-text-fallback">${ls.map((l,i)=>`<div><span>${esc(l)}</span><strong>${vs[i]}</strong><i style="width:${Math.max(2,vs[i]/Math.max(1,...vs)*100)}%"></i></div>`).join('')}</div>`;});return;}Chart.defaults.font.family="'DM Sans', sans-serif";Chart.defaults.color='#7085a1';configs.forEach(([id,ls,vs,kind])=>{const hero=id==='hero-chart',donut=kind==='doughnut';charts.push(new Chart($('#'+id),{type:kind,data:{labels:ls,datasets:[{data:vs,backgroundColor:hero?'rgba(255,255,255,.14)':donut?colors:'#96c4f5',borderColor:hero?'#ffffff':donut?'#f8fbff':'#96c4f5',borderWidth:hero?3:donut?3:0,borderRadius:kind==='bar'?5:0,fill:hero,tension:.4,pointRadius:hero?3:0,pointBackgroundColor:'#fff',maxBarThickness:25}]},options:{maintainAspectRatio:false,cutout:donut?'73%':undefined,plugins:{legend:{display:donut,position:'bottom',labels:{boxWidth:8,boxHeight:8,usePointStyle:true,padding:13,font:{size:11}}},tooltip:{displayColors:false}},...(donut?{}:{scales:{x:{border:{display:false},grid:{display:false},ticks:{color:hero?'#edfaff':'#7085a1',font:{size:11}}},y:{beginAtZero:true,border:{display:false},grid:{color:hero?'rgba(255,255,255,.12)':'#e5edf7'},ticks:{display:!hero,precision:0,maxTicksLimit:4}}}})}}));});}
function table(headers,rows){return `<div class="table-scroll"><table class="permit-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(cells=>`<tr>${cells.map((c,i)=>`<td data-label="${headers[i]}">${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function inlineFilterBar(kind){const cityFilter=['records','borrowers','firearms','locations'].includes(kind);return `<div class="filter-bar"><div class="search-field"><label for="search">Cari ${kind==='records'?'data monitoring':'data'}</label><input id="search" data-filter="q" value="${esc(filters.q||'')}" placeholder="Nama, nomor referensi, atau kata kunci…"></div>${cityFilter?`<div class="filter-field"><label for="filter-city">Kota</label><select id="filter-city" data-filter="city"><option value="">Semua kota</option>${opts(db.cities,filters.city)}<option value="unknown" ${filters.city==='unknown'?'selected':''}>Belum dipetakan</option></select></div>`:''}${['records','firearms'].includes(kind)?`<div class="filter-field"><label for="filter-type">Jenis</label><select id="filter-type" data-filter="type"><option value="">Semua jenis</option>${opts(db.types.map(t=>({id:t.id,name:t.name+' · '+t.category})),filters.type)}</select></div><div class="filter-field"><label for="filter-location">Lokasi</label><select id="filter-location" data-filter="location"><option value="">Semua lokasi</option>${opts(db.locations,filters.location)}<option value="unknown" ${filters.location==='unknown'?'selected':''}>Belum tercatat</option></select></div>`:''}${['records','documents'].includes(kind)?`<div class="filter-field"><label for="filter-status">Status dokumen</label><select id="filter-status" data-filter="status"><option value="">Semua status</option>${opts(['Aktif','Segera berakhir','Expired','Belum lengkap','Belum mulai','Awal belum tercatat'],filters.status)}</select></div><div class="filter-field"><label for="filter-date">Tanggal akhir hingga</label><input type="date" id="filter-date" data-filter="end" value="${esc(filters.end||'')}"></div>`:''}${['borrowers','cities'].includes(kind)?`<div class="filter-field"><label for="filter-state">Status master</label><select id="filter-state" data-filter="active"><option value="">Semua status</option>${opts(kind==='borrowers'?['Aktif','Nonaktif','Belum diketahui']:['Aktif','Nonaktif'],filters.active)}</select></div>`:''}<button class="btn ghost" data-action="reset">Reset</button></div>`;}
function selectedCity(value){return !filters.city||(filters.city==='unknown'?!value:filters.city===value);}
function listData(kind){let items=db[({records:'records',borrowers:'borrowers',firearms:'assets',documents:'documents',locations:'locations',cities:'cities'})[kind]].slice();return items.filter(x=>{let text=Object.values(x).join(' '),pass=true;if(kind==='records'){const b=get('borrowers',x.borrowerId),a=get('assets',x.assetId),ds=recordDocs(x.id);text+=[b?.name,city(x.cityId),a?.model,a?.serial,type(a).name,ds.map(d=>d.number).join(' ')].join(' ');pass=selectedCity(x.cityId)&&(!filters.type||a?.typeId===filters.type)&&(!filters.location||(filters.location==='unknown'?!a?.locationId:a?.locationId===filters.location))&&(!filters.status||ds.some(d=>docStatus(d)===filters.status))&&(!filters.end||ds.some(d=>d.end&&d.end<=filters.end));}else if(kind==='firearms'){text+=' '+type(x).name+' '+type(x).category;pass=selectedCity(get('locations',x.locationId)?.cityId)&&(!filters.type||x.typeId===filters.type)&&(!filters.location||(filters.location==='unknown'?!x.locationId:x.locationId===filters.location));}else if(kind==='documents'){const r=get('records',x.recordId);text+=' '+get('borrowers',r?.borrowerId)?.name;pass=(!filters.status||docStatus(x)===filters.status)&&(!filters.end||x.end&&x.end<=filters.end);}else if(kind==='borrowers'||kind==='locations')pass=selectedCity(x.cityId);if(filters.active)pass=pass&&(filters.active==='Belum diketahui'?!!x.activityUnknown:!x.activityUnknown&&x.active===(filters.active==='Aktif'));return pass&&(!filters.q||text.toLocaleLowerCase('id').includes(filters.q.toLocaleLowerCase('id')));});}
function paginated(kind){const items=listData(kind);const max=Math.max(1,Math.ceil(items.length/7));page=Math.max(1,Math.min(page,max));const part=items.slice((page-1)*7,page*7);let result='';if(kind==='records')result=table(['Register / Pemegang','Kota / Wilayah','Senjata / Alat','Dokumen','Tanggal akhir tercatat','Status sumber / Lokasi','Aksi'],part.map(r=>{const b=get('borrowers',r.borrowerId),a=get('assets',r.assetId);return [`<a href="#/detail/${r.id}"><strong>${esc(b?.name)}</strong><small>${esc(r.number)}</small></a>`,`${esc(city(r.cityId))}<small>${esc(r.jurisdiction)}</small>`,`<strong>${esc(type(a).name)} · ${esc(a?.model)}</strong><small>${esc(a?.caliber)} · ${esc(a?.serial)}</small>`,`<span class="doc-count">${recordDocs(r.id).length} referensi</span>`,date(latestExpiry(r)),`<span class="raw-label">${esc(r.rawStatus)}</span><small>${esc(get('locations',a?.locationId)?.name||'Lokasi belum tercatat')}</small>`,link('Detail',`detail/${r.id}`,'ghost','arrow')];}));if(kind==='borrowers')result=table(['Peminjam','Kota','Pekerjaan / Jabatan','Register','Status','Aksi'],part.map(b=>[`<div class="person-cell"><span class="avatar">${esc(b.name.split(' ').map(s=>s[0]).slice(0,2).join(''))}</span><span><strong>${esc(b.name)}</strong><small>${esc(b.code)}</small></span></div>`,esc(city(b.cityId)),`${esc(b.occupation)}<small>${esc(b.position)}</small>`,String(db.records.filter(r=>r.borrowerId===b.id).length),badge(b.activityUnknown?'Belum diketahui':b.active?'Aktif':'Nonaktif'),link('Detail',`borrower/${b.id}`,'ghost','arrow')]));if(kind==='firearms')result=table(['Senjata / Alat','Jenis / Kategori','Kaliber','Nomor seri','Lokasi','Aksi'],part.map(a=>[`<strong>${esc(a.model)}</strong><small>${esc(a.code)}</small>`,`${esc(type(a).name)}<small>${esc(type(a).category)}</small>`,esc(a.caliber),`<span class="serial">${esc(a.serial)}</span>`,esc(get('locations',a.locationId)?.name||'Belum tercatat'),link('Detail',`firearm/${a.id}`,'ghost','arrow')]));if(kind==='documents')result=table(['Dokumen eksternal','Pemegang / Register','Mulai','Berlaku hingga','Status waktu','Arsip'],part.map(d=>{const r=get('records',d.recordId);return [`<strong>${esc(d.number)}</strong><small>${esc(d.kind)}</small>`,`${esc(get('borrowers',r?.borrowerId)?.name)}<small>${esc(r?.number)}</small>`,date(d.start),d.precision==='day'?date(d.end):esc(d.expiryRaw||'Belum tercatat'),badge(docStatus(d)),link('Lihat',`document/${d.id}`,'ghost','file')];}));if(kind==='cities')result=table(['Kota','Provinsi','Alias','Register','Status','Aksi'],part.map(c=>[`<strong>${esc(c.name)}</strong>`,esc(c.province),c.aliases.map(a=>`<span class="alias-chip">${esc(a)}</span>`).join(' ')||'—',String(db.records.filter(r=>r.cityId===c.id).length),badge(c.active?'Aktif':'Nonaktif'),admin()?`<button class="btn ghost" data-action="city" data-id="${c.id}">${icon('edit')}Edit</button>`:'<span class="muted">Read only</span>']));if(kind==='locations')result=`<div class="location-grid">${part.map(l=>`<section class="location-card"><span class="equipment-icon">${icon('warehouse')}</span><div class="location-label">${esc(l.code)} · ${esc(l.kind)}</div><h2>${esc(l.name)}</h2><p>${esc(l.address)}</p><p>${icon('pin')} ${esc(city(l.cityId))}</p><div class="location-count"><strong>${db.assets.filter(a=>a.locationId===l.id).length}</strong><span>aset tercatat<br><small>Bukan saldo stok tersedia</small></span></div><button class="btn" data-action="location-assets" data-id="${l.id}">Lihat aset ${icon('arrow')}</button></section>`).join('')}</div>`;return (items.length?result:empty())+`<div class="pagination"><span>${items.length?`${(page-1)*7+1}–${Math.min(page*7,items.length)} dari ${items.length}`:'0'} data</span><div class="actions"><button class="btn" data-action="page" data-step="-1" ${page===1?'disabled':''} aria-label="Halaman sebelumnya">←</button><span>${page} / ${max}</span><button class="btn" data-action="page" data-step="1" ${page===max?'disabled':''} aria-label="Halaman berikutnya">→</button></div></div>`;}
function listPage(kind){const titles={records:['Data monitoring','Register pemegang izin, aset, dan dokumen dari sistem eksternal.'],borrowers:['Peminjam & pemegang izin','Profil orang yang terhubung dengan data monitoring.'],firearms:['Senjata & alat','Identitas aset terstruktur, jenis, dan lokasi tercatat.'],documents:['Dokumen eksternal','Referensi kartu, buku, dan arsip dari sistem lain.'],locations:['Lokasi & gudang','Lokasi aset berdasarkan informasi terakhir yang tercatat.'],cities:['Master kota','Nama kota, provinsi, dan alias untuk konsistensi data.']};return heading(...titles[kind],admin()?(kind==='records'?link('Import Excel','import','','upload')+link('Tambah Data','add','primary','plus'):kind==='cities'?'<button class="btn primary" data-action="city">'+icon('plus')+'Tambah kota</button>':''):'')+`<section class="panel">${filterBar(kind)}<div id="results">${paginated(kind)}</div></section>`;}
const info=(label,value)=>`<div class="info-item"><small>${label}</small><strong>${esc(value||'Belum tercatat')}</strong></div>`;
function photo(owner,entity){const f=get('files',owner.photoId);return `<div class="photo-placeholder">${f?.dataUrl?`<img src="${esc(f.dataUrl)}" alt="Foto ${esc(owner.name||owner.model)}">`:`${icon(entity==='borrower'?'users':'image')}<span>${entity==='borrower'?'Foto peminjam':'Foto aset'}</span><small>Belum diunggah</small>`}</div>${admin()?`<button class="btn ghost" data-action="photo" data-entity="${entity}" data-id="${owner.id}">${icon('upload')}Unggah foto</button>`:''}`;}
function documentsTable(id){return table(['Nomor dokumen / Jenis','Mulai','Berlaku hingga','Status waktu','Arsip'],recordDocs(id).map(d=>[`<strong>${esc(d.number)}</strong><small>${esc(d.kind)}</small>`,date(d.start),d.precision==='day'?date(d.end):esc(d.expiryRaw||'Belum tercatat'),badge(docStatus(d)),link('Lihat',`document/${d.id}`,'ghost','file')]));}
function filesSection(recordId,documentId=''){const files=db.files.filter(f=>f.recordId===recordId&&(!documentId||f.documentId===documentId));return `<div class="panel-head"><div><h2>Arsip file & PDF</h2><p>Lampiran dokumen dari sistem eksternal</p></div>${admin()?`<button class="btn" data-action="pdf-upload" data-id="${recordId}" data-document="${documentId}">${icon('upload')}Unggah PDF</button>`:''}</div><div class="panel-body files-list">${files.length?files.map(f=>`<div class="file-row"><span class="equipment-icon">${icon('file')}</span><span class="list-copy"><strong>${esc(f.name)}</strong><small>${f.metadataOnly?'Metadata arsip · File belum tersedia':`${Math.ceil(f.size/1024)} KB · ${date(f.uploadedAt)}`}</small></span>${f.dataUrl?`<button class="btn ghost" data-action="view-file" data-id="${f.id}">Preview</button>`:badge('Metadata')}</div>`).join(''):'<p class="muted">Belum ada lampiran. Nomor referensi tetap dapat dipantau tanpa PDF.</p>'}</div>`;}
function detail(r){const b=get('borrowers',r.borrowerId),a=get('assets',r.assetId);return heading(r.number,'Detail register monitoring dari sistem eksternal.',link('Kembali','records','','back')+(admin()?link('Edit Data',`edit/${r.id}`,'primary','edit'):''))+`<div class="detail-grid"><div class="detail-main"><section class="panel"><div class="panel-head"><h2>Peminjam / pemegang izin</h2>${link('Profil',`borrower/${b.id}`,'ghost','arrow')}</div><div class="panel-body profile-detail">${photo(b,'borrower')}<div class="field-grid">${info('Nama',b.name)}${info('Kode peminjam',b.code)}${info('Kota domisili',city(b.cityId))}${info('Pekerjaan / Jabatan',b.occupation+' / '+b.position)}<div class="full">${info('Alamat',b.address)}</div></div></div></section><section class="panel"><div class="panel-head"><h2>Identitas senjata / alat</h2>${link('Detail aset',`firearm/${a.id}`,'ghost','arrow')}</div><div class="panel-body"><div class="field-grid">${info('Jenis / Kategori',type(a).name+' / '+type(a).category)}${info('Merek / Model',a.model)}${info('Kaliber',a.caliber)}${info('Nomor seri',a.serial)}</div></div></section></div><aside class="detail-side"><section class="panel"><div class="panel-head"><h2>Register sumber</h2></div><div class="panel-body"><div class="field-grid">${info('No sumber',r.sourceNo)}${info('Tahun register',r.sourceYear)}${info('TAKAH',r.takah)}${info('Kota register',city(r.cityId))}<div class="full">${info('Wilayah / Yurisdiksi',r.jurisdiction)}</div><div class="full">${info('Status mentah sumber',r.rawStatus)}</div></div></div></section><section class="panel location-summary"><div class="panel-body"><span class="equipment-icon">${icon('warehouse')}</span><h3>Lokasi terakhir tercatat</h3><p>${esc(get('locations',a.locationId)?.name||'Belum tercatat')}</p><small>Lokasi gudang tidak otomatis berarti aset tersedia.</small></div></section></aside></div><section class="panel section-gap"><div class="panel-head"><div><h2>Referensi kartu & buku</h2><p>${recordDocs(r.id).length} dokumen terpisah · masing-masing memiliki masa berlaku</p></div><span class="badge neutral">Arsip eksternal</span></div>${documentsTable(r.id)}</section><div class="detail-grid section-gap"><section class="panel">${filesSection(r.id)}</section><section class="panel"><div class="panel-head"><h2>Catatan & pembaruan</h2></div><div class="panel-body"><p>${esc(r.notes||'Tidak ada catatan.')}</p><div class="timeline">${r.history.slice().reverse().map(h=>`<div class="timeline-item"><h3>${esc(h.title)}</h3><p>${esc(h.actor)} · ${date(h.date)}</p></div>`).join('')}</div></div></section></div>`;}
function associatedRecords(rows){return rows.length?table(['Register','Peminjam','Senjata / Alat','Referensi','Aksi'],rows.map(r=>[esc(r.number),esc(get('borrowers',r.borrowerId)?.name),esc(get('assets',r.assetId)?.model),String(recordDocs(r.id).length),link('Detail',`detail/${r.id}`,'ghost','arrow')])):empty('Belum ada register terhubung.');}
function borrowerDetail(b){return heading(b.name,'Profil peminjam dan register yang terhubung.',link('Kembali','borrowers','','back')+(admin()?`<button class="btn primary" data-action="borrower-edit" data-id="${b.id}">${icon('edit')}Edit profil</button>`:''))+`<section class="panel"><div class="panel-body entity-detail"><div>${photo(b,'borrower')}</div><div class="field-grid">${info('Kode',b.code)}${info('Status master',b.activityUnknown?'Belum diketahui':b.active?'Aktif':'Nonaktif')}${info('Kota',city(b.cityId))}${info('Pekerjaan',b.occupation)}${info('Jabatan',b.position)}${info('Alamat',b.address)}</div></div></section><section class="panel section-gap"><div class="panel-head"><div><h2>Register terhubung</h2><p>Satu peminjam dapat memiliki beberapa aset dan dokumen.</p></div></div>${associatedRecords(db.records.filter(r=>r.borrowerId===b.id))}</section>`;}
function firearmDetail(a){return heading(a.model,'Identitas aset dan keterkaitan dokumen eksternal.',link('Kembali','firearms','','back')+(admin()?`<button class="btn primary" data-action="asset-edit" data-id="${a.id}">${icon('edit')}Edit aset</button>`:''))+`<section class="panel"><div class="panel-body entity-detail"><div>${photo(a,'asset')}</div><div class="field-grid">${info('Kode aset',a.code)}${info('Jenis / Kategori',type(a).name+' / '+type(a).category)}${info('Kaliber',a.caliber)}${info('Nomor seri',a.serial)}${info('Lokasi',get('locations',a.locationId)?.name)}${info('Catatan',a.notes)}</div></div></section><section class="panel section-gap"><div class="panel-head"><div><h2>Riwayat register monitoring</h2><p>Keterkaitan register, bukan riwayat serah terima fisik.</p></div></div>${associatedRecords(db.records.filter(r=>r.assetId===a.id))}</section>`;}
function documentDetail(d){const r=get('records',d.recordId);return heading('Dokumen eksternal',d.number,link('Kembali','documents','','back')+link('Lihat register',`detail/${r.id}`,'','file'))+`<div class="detail-grid"><section class="panel"><div class="panel-head"><h2>Metadata dokumen</h2>${badge(docStatus(d))}</div><div class="panel-body"><div class="field-grid">${info('Nomor referensi',d.number)}${info('Jenis dokumen',d.kind)}${info('Pemegang',get('borrowers',r.borrowerId)?.name)}${info('Register',r.number)}${info('Tanggal mulai',date(d.start))}${info('Berlaku hingga',d.precision==='day'?date(d.end):d.expiryRaw||'Belum tercatat')}${info('Sumber',d.source)}${info('Presisi tanggal',d.precision==='day'?'Tanggal lengkap':d.precision==='month'?'Bulan, tanpa tanggal pasti':'Belum lengkap')}</div><div class="context-note">${icon('shield')}<span>Referensi ini dicatat dari sistem lain. Tampilan ini adalah metadata arsip, bukan dokumen izin resmi.</span></div></div></section><section class="panel">${filesSection(r.id,d.id)}</section></div>`;}
function documentInput(d={}){return `<div class="document-input"><label>Nomor referensi<input name="docNumber" value="${esc(d.number||'')}" placeholder="Nomor dari sistem eksternal" required><input type="hidden" name="docId" value="${esc(d.id||'')}"></label><label>Jenis<input name="docKind" value="${esc(d.kind||'Referensi eksternal')}" required></label><label>Mulai<input type="date" name="docStart" value="${esc(d.start||'')}"></label><label>Berlaku hingga<input type="date" name="docEnd" value="${esc(d.end||'')}"></label><label>Keterangan tanggal<input name="docRaw" value="${esc(d.expiryRaw||'')}" placeholder="Opsional jika tanggal belum pasti"></label></div>`;}
function recordForm(r){const isEdit=!!r;return heading(isEdit?'Edit data monitoring':'Tambah data monitoring','Catat referensi dari sistem eksternal. Tanggal yang belum diketahui dapat dikosongkan.',link('Kembali',r?`detail/${r.id}`:'records','','back'))+`<form id="record-form" data-id="${r?.id||''}" class="panel"><div class="panel-head"><h2>Informasi register</h2><span class="badge neutral">${r?esc(r.number):'Register monitoring baru'}</span></div><div class="panel-body"><div class="field-grid"><div><label>Nomor register<input name="number" required value="${esc(r?.number||'REG-LOCAL-'+String(db.records.length+1).padStart(4,'0'))}"></label></div><div><label>No sumber<input name="sourceNo" value="${esc(r?.sourceNo||'')}"></label></div><div><label>Peminjam<select name="borrowerId" required><option value="">Pilih peminjam</option>${opts(db.borrowers.map(b=>({id:b.id,name:b.name+' · '+b.code})),r?.borrowerId)}</select></label><button type="button" class="btn ghost" data-action="borrower-edit">${icon('plus')}Peminjam baru</button></div><div><label>Senjata / Alat<select name="assetId" required><option value="">Pilih aset</option>${opts(db.assets.map(a=>({id:a.id,name:a.model+' · '+a.serial})),r?.assetId)}</select></label><button type="button" class="btn ghost" data-action="asset-edit">${icon('plus')}Aset baru</button></div><div><label>Kota register<select name="cityId"><option value="">Belum dipetakan</option>${opts(db.cities,r?.cityId)}</select></label></div><div><label>Wilayah / Yurisdiksi<input name="jurisdiction" value="${esc(r?.jurisdiction||'')}"></label></div><div><label>Tahun register<input name="sourceYear" type="number" min="1900" max="2200" value="${r?.sourceYear||new Date().getFullYear()}" required></label></div><div><label>TAKAH / Referensi berkas<input name="takah" value="${esc(r?.takah||'')}"></label></div><div class="full"><label>Status mentah dari sumber<input name="rawStatus" value="${esc(r?.rawStatus||'BELUM TERCATAT')}" placeholder="Misal: SUDAH DIPERPANJANG"></label></div><div class="full"><label>Catatan<textarea name="notes" rows="3">${esc(r?.notes||'')}</textarea></label></div></div><hr class="section-divider"><h2>Referensi kartu / buku</h2><p class="hint">Satu blok untuk satu dokumen. Masa berlaku tidak digabung menjadi satu status register.</p><div id="document-inputs">${(r?recordDocs(r.id):[{}]).map(documentInput).join('')}</div><button class="btn" data-action="add-document" type="button">${icon('plus')}Tambah referensi</button><p id="form-error" class="error" role="alert"></p><div class="form-actions">${link('Batal',r?`detail/${r.id}`:'records')}<button class="btn primary" type="submit">Simpan data monitoring</button></div></div></form>`;}
function userPage(){return heading('Manajemen user','Akses administrator dan viewer untuk workspace lokal.',`<button class="btn primary" data-action="add-user">${icon('plus')}Tambah user</button>`)+`<section class="panel">${table(['Nama','Username','Role','Status','Aksi'],db.users.map(u=>[`<strong>${esc(u.name)}</strong>`,esc(u.username),esc(u.role==='Admin'?'Admin':'Viewer'),badge(u.active?'Aktif':'Nonaktif'),`<button class="btn" data-action="toggle-user" data-id="${u.id}" ${u.id===session.id?'disabled':''}>${u.active?'Nonaktifkan':'Aktifkan'}</button>`]))}<div class="panel-foot">Akun sendiri tidak dapat dinonaktifkan. Viewer hanya memiliki akses baca.</div></section>`;}
function importPage(){return heading('Import data Excel','Baca register, pisahkan referensi multiline, lalu tinjau sebelum menyimpan.',`<button class="btn" data-action="template">${icon('download')}Template</button>`)+`<div class="import-layout"><section class="panel"><div class="panel-body"><div class="import-steps"><span class="active">1 <b>Upload</b></span><i></i><span>2 <b>Tinjau & mapping</b></span><i></i><span>3 <b>Simpan</b></span></div><div id="dropzone" class="dropzone">${icon('upload')}<h2>Letakkan file Excel di sini</h2><p>.xlsx, .xls, atau .csv · Maks. 5 MB · 1.000 baris</p><button class="btn primary" data-action="choose-file">Pilih file</button><input type="file" id="excel-file" accept=".xlsx,.xls,.csv" hidden><div id="file-name" class="hint">${esc(importName||'Semua sheet berheader yang dikenali akan dibaca.')}</div></div><button class="btn ghost" data-action="sample-import">${icon('spark')}Coba simulasi import</button></div></section><aside class="panel import-help"><div class="panel-head"><h2>Struktur yang dikenali</h2></div><div class="panel-body"><div class="help-step"><span>01</span><div><strong>Identitas senjata</strong><p>Jenis, merek/model, kaliber, serial: empat atribut satu aset.</p></div></div><div class="help-step"><span>02</span><div><strong>Kartu / buku</strong><p>Setiap baris tidak kosong menjadi referensi dokumen sendiri.</p></div></div><div class="help-step"><span>03</span><div><strong>Masa berlaku</strong><p>Posisi baris kosong dipertahankan untuk pasangan tanggal.</p></div></div><div class="context-note">${icon('pin')}<span>“Jaksel” dapat dipetakan melalui alias master kota. Wilayah sumber tetap disimpan terpisah.</span></div></div></aside></div><div id="import-preview">${importPreview()}</div><section class="panel section-gap"><div class="panel-head"><div><h2>Riwayat import</h2><p>Ringkasan proses pada browser ini</p></div></div>${db.batches.length?table(['File / Waktu','Baris','Baru','Update','Dilewati / Terblokir','Status'],db.batches.slice().reverse().map(b=>[`<strong>${esc(b.name)}</strong><small>${date(b.date)}</small>`,String(b.total),String(b.imported),String(b.updated),`${b.skipped} / ${b.blocked}`,badge(b.status,'active')])):empty('Belum ada batch import.')}</section>`;}
const norm=v=>String(v??'').trim().replace(/\s+/g,' ').toLocaleLowerCase('id');
function cityMatch(raw){const matches=db.cities.filter(c=>c.active&&[c.name,...c.aliases].some(a=>norm(a)===norm(raw)));return matches.length===1?matches[0].id:'';}
function assetMatches(r){return db.assets.filter(a=>norm(a.serial)===norm(r.serial));}
function borrowerMatches(r){return db.borrowers.filter(b=>norm(b.name)===norm(r.name)&&norm(b.address)===norm(r.address));}
function rowKey(r){return [r.category,r.sourceNo,r.year,r.serial].map(norm).join('|');}
function duplicateRecord(r){return db.records.find(x=>x.sourceKey===rowKey(r));}
function rowIssues(r){const errors=[...(r.errors||[])],warnings=[...(r.warnings||[])];if(!r.cityId)errors.push('Pilih kota register atau tandai belum diketahui.');if(r.cityId==='unknown')warnings.push('Kota register disimpan tanpa mapping.');const am=assetMatches(r),bm=borrowerMatches(r);if(am.length>1)errors.push('Nomor seri memiliki lebih dari satu kandidat aset.');else if(am.length===1&&(norm(am[0].model)!==norm(r.model)||norm(type(am[0]).name)!==norm(r.type)||norm(type(am[0]).category)!==norm(r.category)||norm(am[0].caliber)!==norm(r.caliber)))errors.push('Nomor seri cocok, tetapi identitas aset berbeda.');if(bm.length>1)errors.push('Peminjam cocok dengan beberapa master; selesaikan di data master.');if(!bm.length&&db.borrowers.some(b=>norm(b.name)===norm(r.name)))errors.push('Nama peminjam ada, tetapi alamat berbeda; perlu rekonsiliasi master.');return {errors:[...new Set(errors)],warnings:[...new Set(warnings)]};}
function importPreview(){if(!importRows.length)return '';const valid=importRows.filter(r=>!rowIssues(r).errors.length).length;const duplicates=importRows.filter(duplicateRecord).length;return `<section class="panel section-gap"><div class="panel-head"><div><h2>Tinjau hasil pembacaan</h2><p>${esc(importName)} · Posisi newline dipertahankan</p></div><span class="badge neutral">Belum disimpan</span></div><div class="panel-body"><div class="import-metrics"><div><small>Total baris</small><strong>${importRows.length}</strong></div><div class="green-text"><small>Valid</small><strong>${valid}</strong></div><div class="red-text"><small>Terblokir</small><strong>${importRows.length-valid}</strong></div><div><small>Duplikat terdeteksi</small><strong>${duplicates}</strong></div></div><label for="duplicate-mode">Jika register sumber sudah ada</label><select id="duplicate-mode" class="mode-select"><option value="skip" ${importMode==='skip'?'selected':''}>Lewati duplikat (default)</option><option value="update" ${importMode==='update'?'selected':''}>Perbarui register & referensi yang cocok</option></select><p class="hint">Aturan pencocokan: kategori + nomor sumber + tahun + serial. Peminjam: nama & alamat. Aset: serial dan identitas yang sama. Dokumen lama yang tidak ada di file tetap disimpan.</p></div>${table(['Sumber / Peminjam','Identitas aset','Dokumen / Tanggal','Mapping kota register','Master / Duplikat','Validasi'],importRows.map((r,i)=>{const issues=rowIssues(r);return [`<strong>${esc(r.name)}</strong><small>${esc(r.sheet)} · baris ${r.row}</small>`,`<strong>${esc(r.type)} · ${esc(r.model)}</strong><small>${esc(r.caliber)} · ${esc(r.serial)}</small>`,r.docs.map(d=>`<div class="preview-doc"><strong>${esc(d.number)}</strong><small>${esc(d.end||d.expiryRaw||'Tanggal kosong')} · slot ${d.lineNo}</small></div>`).join('')||'Tidak ada',`<small>Sumber: ${esc(r.cityRaw||'kosong')}</small><select data-map-city="${i}" aria-label="Kota baris ${r.row}"><option value="">Pilih mapping</option>${opts(db.cities,r.cityId)}<option value="unknown" ${r.cityId==='unknown'?'selected':''}>Belum diketahui</option></select>`,`<small>Peminjam: ${borrowerMatches(r).length?'cocok':'baru'}<br>Aset: ${assetMatches(r).length?'cocok':'baru'}</small>${badge(duplicateRecord(r)?importMode==='skip'?'Dilewati':'Diperbarui':'Register baru','neutral')}`,issues.errors.length?`<div class="error">${issues.errors.map(esc).join('<br>')}</div>`:badge('Siap disimpan','active')+(issues.warnings.length?`<div class="warning-note">${issues.warnings.map(esc).join('<br>')}</div>`:'')];}))}<div class="panel-body"><div class="context-note">${icon('shield')}<span>Hanya baris valid yang disimpan. Status dan tanggal dari sumber tidak menjadi bukti baru. Kota register tidak otomatis menjadi kota domisili peminjam.</span></div><div class="form-actions"><button class="btn" data-action="clear-import">Batalkan preview</button><button class="btn primary" data-action="commit-import" ${valid?'':'disabled'}>${icon('upload')}Simpan ${valid} baris valid</button></div></div></section>`;}
function splitLines(v){return String(v??'').replace(/\r\n/g,'\n').replace(/\r/g,'\n').split('\n').map(s=>s.trim());}
function parseDate(v){if(v instanceof Date)return {end:localDay(v),precision:'day',expiryRaw:''};const s=String(v??'').trim();if(!s)return {end:'',precision:'unknown',expiryRaw:''};if(validDate(s))return {end:s,precision:'day',expiryRaw:s};const m=s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);if(m){const end=`${m[3]}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`;if(validDate(end))return {end,precision:'day',expiryRaw:s};}if(/^[a-zA-Z]+\s+\d{4}$/.test(s))return {end:'',precision:'month',expiryRaw:s};return {end:'',precision:'unknown',expiryRaw:s,error:'Format tanggal tidak dikenali: '+s};}
function parseSourceRow(obj,sheet,row){const h={};Object.entries(obj).forEach(([k,v])=>h[norm(k)]=v);const field=(...keys)=>{for(const k of keys)if(h[k]!==undefined)return h[k];return '';};const identity=splitLines(field('identitas senpi'));const errors=[],warnings=[];if(identity.length!==4||identity.some(v=>!v))errors.push('Identitas senpi harus memiliki 4 baris atribut.');const nums=splitLines(field('no kartu / buku','no kartu/buku'));const rawDate=field('berlaku s/d');const dates=rawDate instanceof Date?[rawDate]:splitLines(rawDate);const nonempty=nums.filter(Boolean);if(dates.length===1&&String(dates[0]).trim()&&nonempty.length>1)errors.push('Tanggal tunggal berhadapan dengan beberapa dokumen; pasangan ambigu.');if(dates.length>nums.length&&dates.slice(nums.length).some(x=>String(x).trim()))errors.push('Ada tanggal tanpa nomor dokumen.');const docs=[];nums.forEach((number,i)=>{if(!number){if(dates[i]&&String(dates[i]).trim())errors.push('Slot tanggal '+(i+1)+' tidak memiliki nomor dokumen.');return;}const dt=parseDate(dates[i]);if(dt.error)errors.push(dt.error);if(!dt.end)warnings.push('Ada tanggal kosong/parsial.');docs.push({number,kind:number.split('/')[0].trim()||'Referensi eksternal',start:'',...dt,lineNo:i+1});});if(!docs.length)errors.push('Nomor kartu/buku kosong.');if(new Set(docs.map(d=>norm(d.number))).size!==docs.length)errors.push('Nomor dokumen berulang dalam satu register.');const cityRaw=String(field('kota','wilayah hukum','polres')).trim();if(!field('kota')&&cityRaw)warnings.push('Pastikan wilayah sumber sesuai kota register yang dipilih.');const result={sheet,row,sourceNo:String(field('no')).trim(),year:String(field('tahun')).trim(),takah:String(field('takah')).trim(),name:String(field('nama')).trim(),address:String(field('alamat')).trim(),occupation:String(field('pekerjaan')).trim(),position:String(field('jabatan')).trim(),type:identity[0]||'',model:identity[1]||'',caliber:identity[2]||'',serial:identity[3]||'',category:String(field('kategori')||(/karet/i.test(sheet)?'Peluru karet':/tajam/i.test(sheet)?'Peluru tajam':'')),cityRaw,cityId:cityMatch(cityRaw),rawStatus:String(field('status')).trim(),notes:String(field('keterangan')).trim(),docs,errors,warnings};if(!result.category)errors.push('Kategori belum diketahui; gunakan nama sheet SENPI PELURU TAJAM/KARET atau kolom KATEGORI.');if(!result.name||!result.address||!result.sourceNo)errors.push('Nama, alamat, dan nomor sumber wajib diisi.');if(!/^\d{4}$/.test(result.year))errors.push('Tahun harus empat digit.');if(/^\d+$/.test(result.caliber))warnings.push('Satuan kaliber tidak disebutkan; label dipertahankan.');return result;}
async function parseExcel(file){if(!file)return;if(file.size>5*1024*1024){toast('Maksimum ukuran file 5 MB.');return;}if(!/\.(xlsx|xls|csv)$/i.test(file.name)){toast('Pilih file Excel atau CSV.');return;}if(!window.XLSX){toast('SheetJS belum tersedia. Gunakan simulasi atau hubungkan internet dan muat ulang.');return;}try{const book=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:true});const rows=[];const skipped=[];for(const name of book.SheetNames){const matrix=XLSX.utils.sheet_to_json(book.Sheets[name],{header:1,defval:'',blankrows:true});const hi=matrix.findIndex(row=>row.some(v=>norm(v)==='nama')&&row.some(v=>norm(v)==='identitas senpi'));if(hi<0){skipped.push(name);continue;}const heads=matrix[hi];for(let i=hi+1;i<matrix.length;i++){if(matrix[i].every(v=>v===''||v===null))continue;const obj={};heads.forEach((h,j)=>{if(String(h).trim())obj[String(h)]=matrix[i][j]??'';});rows.push(parseSourceRow(obj,name,i+1));if(rows.length>1000)throw Error('Maksimum 1.000 baris per import.');}}if(!rows.length)throw Error('Tidak ada sheet dengan header NAMA dan IDENTITAS SENPI. Gunakan template.');const seen=new Set();rows.forEach(r=>{const key=rowKey(r);if(seen.has(key))r.errors.push('Register berulang dalam file yang sama.');seen.add(key);});importRows=rows;importName=file.name;render();if(skipped.length)toast('Sheet tidak dikenali: '+skipped.join(', '));else toast('File dibaca. Tinjau pasangan dokumen dan mapping kota.');}catch(e){toast('File belum dapat diproses: '+e.message);}}
function sampleImport(){importName='Simulasi-register-multiline.xlsx';importRows=[parseSourceRow({'No':'SIM-01','TAHUN':new Date().getFullYear(),'NAMA':'Rendra Pusaka','ALAMAT':'Jl. Simulasi Biru No. 21','PEKERJAAN':'Swasta','JABATAN':'Konsultan','WILAYAH HUKUM':'Jaksel','IDENTITAS SENPI':'PISTOL\nArunika X\nLabel .22\nSIM-ASSET-001','NO KARTU / BUKU':'KARTU-SIM/001\nBUKU-SIM/001','BERLAKU S/D':isoDate(20)+'\n'+isoDate(100),'STATUS':'TERCATAT DI SISTEM SUMBER'},'SENPI PELURU TAJAM',3),parseSourceRow({'No':'SIM-02','TAHUN':new Date().getFullYear(),'NAMA':'Kirana Adiswara','ALAMAT':'Jl. Contoh Puspa No. 8','POLRES':'Tangerang','IDENTITAS SENPI':'REVOLVER\nMentari Z\n9 mm\nSIM-ASSET-002','NO KARTU / BUKU':'KARTU-SIM/002\nBUKU-SIM/002','BERLAKU S/D':'MEI 2025','STATUS':'BELUM DIPERPANJANG'},'SENPI PELURU KARET',4)];render();}
function downloadTemplate(){if(!window.XLSX){toast('Template Excel memerlukan koneksi CDN. Simulasi import tetap dapat digunakan.');return;}const example={'No':'SIM-100','TAKAH':'ARS-SIM-100','TAHUN':new Date().getFullYear(),'WILAYAH HUKUM':'Jaksel','NAMA':'Rendra Pusaka','ALAMAT':'Jl. Simulasi Biru No. 21','PEKERJAAN':'Swasta','JABATAN':'Konsultan','IDENTITAS SENPI':'PISTOL\nArunika X\nLabel .22\nSIM-ASSET-100','NO KARTU / BUKU':'KARTU-SIM/100\nBUKU-SIM/100','BERLAKU S/D':isoDate(30)+'\n'+isoDate(100),'KETERANGAN':'Data fiktif untuk simulasi import.','STATUS':'TERCATAT DI SISTEM SUMBER'};const book=XLSX.utils.book_new();const sheet=XLSX.utils.json_to_sheet([example]);sheet['!cols']=Object.keys(example).map(()=>({wch:27}));XLSX.utils.book_append_sheet(book,sheet,'SENPI PELURU TAJAM');XLSX.writeFile(book,'PermitTrack-template-monitoring.xlsx');}
function commitImport(){if(!admin())return;let imported=0,updated=0,skipped=0,blocked=0;const batchId=uid();importRows.forEach(row=>{if(rowIssues(row).errors.length){blocked++;return;}const existing=duplicateRecord(row);if(existing&&importMode==='skip'){skipped++;return;}let b=borrowerMatches(row)[0];if(!b){b={id:uid(),code:'PJM-LOCAL-'+String(db.borrowers.length+1).padStart(3,'0'),name:row.name,address:row.address,cityId:'',occupation:row.occupation,position:row.position,active:false,photoId:null,activityUnknown:true};db.borrowers.push(b);}let t=db.types.find(t=>norm(t.name)===norm(row.type)&&norm(t.category)===norm(row.category));if(!t){t={id:uid(),name:row.type,category:row.category};db.types.push(t);}let a=assetMatches(row)[0];if(!a){a={id:uid(),code:'AST-LOCAL-'+String(db.assets.length+1).padStart(3,'0'),typeId:t.id,model:row.model,caliber:row.caliber,serial:row.serial,locationId:'',photoId:null,notes:'Diimpor dari register eksternal.'};db.assets.push(a);}const record=existing||{id:uid(),number:`REG-IMP-${String(db.records.length+1).padStart(4,'0')}`,importedAt:isoDate(),history:[]};Object.assign(record,{borrowerId:b.id,assetId:a.id,sourceNo:row.sourceNo,sourceYear:row.year,takah:row.takah,cityId:row.cityId==='unknown'?'':row.cityId,jurisdiction:row.cityRaw,rawStatus:row.rawStatus,notes:row.notes,updatedAt:isoDate(),batchId,sourceKey:rowKey(row),sourceRaw:{sheet:row.sheet,row:row.row}});record.history.push({date:isoDate(),title:existing?'Data diperbarui melalui re-import':'Data eksternal diimpor',actor:session.name});if(!existing){db.records.push(record);imported++;}else updated++;row.docs.forEach(d=>{const old=db.documents.find(x=>x.recordId===record.id&&norm(x.number)===norm(d.number));const value={...d,recordId:record.id,source:importName};if(old)Object.assign(old,value);else db.documents.push({...value,id:uid()});});});db.batches.push({id:batchId,name:importName,date:isoDate(),total:importRows.length,imported,updated,skipped,blocked,status:blocked?'Selesai sebagian':'Selesai'});persist();importRows=[];importName='';render();showModal(`<h2>Ringkasan import</h2><p>Data telah diproses di workspace lokal.</p><div class="summary-stats">${[['Register baru',imported],['Diperbarui',updated],['Duplikat dilewati',skipped],['Baris terblokir',blocked]].map(([t,n])=>`<div><span>${t}</span><strong>${n}</strong></div>`).join('')}</div><p class="hint">Lokasi aset dan status aktif peminjam baru perlu dilengkapi dari sumber yang sesuai.</p><div class="actions"><button class="btn" data-action="close">Tutup</button>${link('Lihat data','records','primary')}</div>`);}
function showModal(html){$('#modal').innerHTML=html;$('#modal').showModal();}
function editor(kind,id){if(!admin())return;const x=get(kind==='borrower'?'borrowers':'assets',id);const field=(label,name,value,required=true)=>`<label>${label}<input name="${name}" value="${esc(value||'')}" ${required?'required':''}></label>`;const content=kind==='borrower'?`${field('Nama peminjam','name',x?.name)}${field('Alamat','address',x?.address)}<label>Kota domisili<select name="cityId"><option value="">Belum dipetakan</option>${opts(db.cities,x?.cityId)}</select></label>${field('Pekerjaan','occupation',x?.occupation,false)}${field('Jabatan','position',x?.position,false)}<label>Status master<select name="state">${opts(['Belum diketahui','Aktif','Nonaktif'],x?.activityUnknown?'Belum diketahui':x?x.active?'Aktif':'Nonaktif':'Belum diketahui')}</select></label>`:`${field('Merek / Model','model',x?.model)}<label>Jenis / Kategori<select name="typeId">${opts(db.types.map(t=>({id:t.id,name:t.name+' · '+t.category})),x?.typeId)}</select></label>${field('Kaliber (label sesuai sumber)','caliber',x?.caliber)}${field('Nomor seri','serial',x?.serial)}<label>Lokasi tercatat<select name="locationId"><option value="">Belum tercatat</option>${opts(db.locations,x?.locationId)}</select></label>${field('Catatan','notes',x?.notes,false)}`;showModal(`<form id="entity-form" data-kind="${kind}" data-id="${id||''}"><h2>${x?'Edit':'Tambah'} ${kind==='borrower'?'peminjam':'aset'}</h2>${content}<p id="entity-error" class="error" role="alert"></p><div class="actions"><button type="button" class="btn" data-action="close">Batal</button><button type="submit" class="btn primary">Simpan</button></div></form>`);}
function cityEditor(id){if(!admin())return;const c=get('cities',id);showModal(`<form id="city-form" data-id="${id||''}"><h2>${c?'Edit':'Tambah'} kota</h2><label>Nama kota<input name="name" value="${esc(c?.name||'')}" required></label><label>Provinsi<input name="province" value="${esc(c?.province||'')}" required></label><label>Alias (pisahkan dengan koma)<input name="aliases" value="${esc(c?.aliases.join(', ')||'')}" placeholder="Contoh: Jaksel"></label><label>Status<select name="active">${opts(['Aktif','Nonaktif'],c?.active===false?'Nonaktif':'Aktif')}</select></label><p id="city-error" class="error" role="alert"></p><div class="actions"><button type="button" class="btn" data-action="close">Batal</button><button class="btn primary" type="submit">Simpan kota</button></div></form>`);}
function uploadFile(kind,id,documentId=''){if(!admin())return;const input=document.createElement('input');input.type='file';input.accept=kind==='pdf'?'application/pdf':'image/jpeg,image/png,image/webp';input.onchange=()=>{const file=input.files[0];if(!file)return;const allowed=kind==='pdf'?['application/pdf']:['image/jpeg','image/png','image/webp'];if(!allowed.includes(file.type)||file.size>1024*1024){toast('Gunakan '+(kind==='pdf'?'PDF':'JPG, PNG, atau WebP')+' maksimum 1 MB untuk penyimpanan lokal.');return;}const reader=new FileReader();reader.onload=()=>{const f={id:uid(),name:file.name,mime:file.type,size:file.size,uploadedAt:isoDate(),dataUrl:reader.result,metadataOnly:false,...(kind==='pdf'?{recordId:id,documentId}:{})};db.files.push(f);if(kind!=='pdf'){const x=get(kind==='borrower'?'borrowers':'assets',id);x.photoId=f.id;}persist();render();toast('File disimpan di browser ini.');};reader.readAsDataURL(file);};input.click();}
function render(){charts.forEach(c=>c.destroy());charts=[];if(session)session=get('users',session.id);if(!session?.active){session=null;$('#app').innerHTML=login();return;}let [route,id]=location.hash.replace(/^#\/?/,'').split('/');route=route||'dashboard';if(route==='permits'){location.hash='/records';return;}if(!admin()&&['import','users','add','edit'].includes(route)){location.hash='/dashboard';toast('Halaman khusus administrator.');return;}let html;const notFound=()=>heading('Data tidak ditemukan','Kembali ke daftar untuk melihat data yang tersedia.',link('Data monitoring','records'));if(['records','borrowers','firearms','documents','locations','cities'].includes(route))html=listPage(route);else switch(route){case'dashboard':html=dashboard();break;case'detail':html=get('records',id)?detail(get('records',id)):notFound();break;case'borrower':html=get('borrowers',id)?borrowerDetail(get('borrowers',id)):notFound();break;case'firearm':html=get('assets',id)?firearmDetail(get('assets',id)):notFound();break;case'document':html=get('documents',id)?documentDetail(get('documents',id)):notFound();break;case'add':html=recordForm();break;case'edit':html=get('records',id)?recordForm(get('records',id)):notFound();break;case'import':html=importPage();break;case'users':html=userPage();break;default:location.hash='/dashboard';return;}$('#app').innerHTML=shell(html,route);document.title=APP_NAME+' · Monitoring';if(route==='dashboard')drawCharts();if(route==='import'){const zone=$('#dropzone');zone.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('drag');});zone.addEventListener('dragleave',()=>zone.classList.remove('drag'));zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('drag');parseExcel(e.dataTransfer.files[0]);});}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const act=b.dataset.action;switch(act){case'quick-login':$('#username').value=b.dataset.role;$('#password').value=b.dataset.role+'123';break;case'logout':sessionStorage.removeItem(SESSION_KEY);session=null;location.hash='/login';render();break;case'menu':$('.sidebar')?.classList.toggle('open');break;case'close':$('#modal').close();break;case'reset':filters={};page=1;render();break;case'page':page+=Number(b.dataset.step);$('#results').innerHTML=paginated(routeNow());break;case'location-assets':location.hash='/firearms';setTimeout(()=>{filters.location=b.dataset.id;render();},0);break;case'choose-file':$('#excel-file').click();break;case'sample-import':if(admin())sampleImport();break;case'template':if(admin())downloadTemplate();break;case'clear-import':importRows=[];importName='';render();break;case'commit-import':commitImport();break;case'city':cityEditor(b.dataset.id);break;case'borrower-edit':editor('borrower',b.dataset.id);break;case'asset-edit':editor('asset',b.dataset.id);break;case'add-document':if(admin())$('#document-inputs').insertAdjacentHTML('beforeend',documentInput());break;case'photo':uploadFile(b.dataset.entity,b.dataset.id);break;case'pdf-upload':uploadFile('pdf',b.dataset.id,b.dataset.document);break;case'view-file':{const f=get('files',b.dataset.id);if(f?.dataUrl){showModal(`<h2>${esc(f.name)}</h2><p>PDF arsip eksternal</p><iframe class="pdf-frame" title="Preview PDF eksternal" src="${esc(f.dataUrl)}"></iframe><div class="actions"><a class="btn" href="${esc(f.dataUrl)}" download="${esc(f.name)}">Unduh PDF</a><button class="btn primary" data-action="close">Tutup</button></div>`);}}break;case'add-user':if(!admin())return;showModal(`<form id="user-form"><h2>Tambah user</h2><label>Nama<input name="name" required></label><label>Username<input name="username" pattern="[a-zA-Z0-9_]{3,30}" title="3–30 huruf, angka, underscore" required></label><label>Password<input type="password" name="password" minlength="6" required></label><label>Role<select name="role"><option value="User">Viewer</option><option>Admin</option></select></label><div id="user-error" class="error"></div><div class="actions"><button class="btn" type="button" data-action="close">Batal</button><button class="btn primary" type="submit">Simpan</button></div></form>`);break;case'toggle-user':if(!admin())return;{const u=get('users',b.dataset.id);if(u&&u.id!==session.id){u.active=!u.active;persist();render();}}break;}});
document.addEventListener('input',e=>{if(e.target.matches('[data-filter]')){filters[e.target.dataset.filter]=e.target.value;page=1;$('#results').innerHTML=paginated(routeNow());syncFilterControls();}});
document.addEventListener('change',e=>{if(e.target.id==='excel-file')parseExcel(e.target.files[0]);if(e.target.matches('[data-map-city]')){importRows[Number(e.target.dataset.mapCity)].cityId=e.target.value;$('#import-preview').innerHTML=importPreview();}if(e.target.id==='duplicate-mode'){importMode=e.target.value;$('#import-preview').innerHTML=importPreview();}});
document.addEventListener('submit',e=>{const form=e.target;if(!['login-form','record-form','entity-form','city-form','user-form'].includes(form.id))return;e.preventDefault();const fd=new FormData(form),v=Object.fromEntries(fd);if(form.id==='login-form'){const u=db.users.find(u=>norm(u.username)===norm(v.username)&&u.password===v.password&&u.active);if(!u){$('#login-error').textContent='Username/password salah atau akun nonaktif.';return;}session=u;sessionStorage.setItem(SESSION_KEY,JSON.stringify(u.id));location.hash='/dashboard';render();return;}if(!admin())return;if(form.id==='record-form'){const old=get('records',form.dataset.id);if(!v.number.trim()||db.records.some(r=>r.id!==old?.id&&norm(r.number)===norm(v.number))){$('#form-error').textContent='Nomor register wajib unik dan tidak kosong.';return;}const ns=fd.getAll('docNumber'),ks=fd.getAll('docKind'),starts=fd.getAll('docStart'),ends=fd.getAll('docEnd'),raw=fd.getAll('docRaw'),ids=fd.getAll('docId');const ds=ns.map((n,i)=>({id:ids[i]||uid(),number:n.trim(),kind:ks[i].trim(),start:starts[i],end:ends[i],expiryRaw:raw[i],precision:ends[i]?'day':'unknown',lineNo:i+1,source:'Input metadata eksternal'}));if(ds.some(d=>!d.number||d.start&&d.end&&d.end<d.start)||new Set(ds.map(d=>norm(d.number))).size!==ds.length){$('#form-error').textContent='Periksa nomor dokumen (wajib unik per register) dan tanggal akhir setelah tanggal mulai.';return;}const r=old||{id:uid(),history:[],importedAt:isoDate(),batchId:'',sourceKey:''};for(const key of ['number','sourceNo','sourceYear','takah','borrowerId','assetId','cityId','jurisdiction','rawStatus','notes'])r[key]=v[key].trim();r.updatedAt=isoDate();r.history.push({date:isoDate(),title:old?'Metadata register diperbarui':'Register eksternal dicatat',actor:session.name});if(!old)db.records.push(r);db.documents=db.documents.filter(d=>d.recordId!==r.id).concat(ds.map(d=>({...d,recordId:r.id})));persist();location.hash='/detail/'+r.id;toast('Data monitoring disimpan.');return;}if(form.id==='entity-form'){const kind=form.dataset.kind;const collection=kind==='borrower'?'borrowers':'assets';let obj=get(collection,form.dataset.id);for(const key of Object.keys(v))v[key]=v[key].trim();if(kind==='asset'&&db.assets.some(a=>a.id!==obj?.id&&norm(a.serial)===norm(v.serial))){$('#entity-error').textContent='Nomor seri sudah digunakan. Pilih aset yang sudah ada.';return;}if(kind==='borrower'&&(!v.name||!v.address)){ $('#entity-error').textContent='Nama dan alamat wajib diisi.';return;}if(kind==='asset'&&(!v.model||!v.serial||!v.caliber)){$('#entity-error').textContent='Identitas aset wajib diisi.';return;}if(!obj){obj={id:uid(),code:(kind==='borrower'?'PJM':'AST')+'-LOCAL-'+String(db[collection].length+1).padStart(3,'0'),photoId:null};db[collection].push(obj);}Object.assign(obj,v);if(kind==='borrower'){obj.active=v.state==='Aktif';obj.activityUnknown=v.state==='Belum diketahui';delete obj.state;}persist();$('#modal').close();const select=$(`#record-form select[name="${kind==='borrower'?'borrowerId':'assetId'}"]`);if(select){select.innerHTML='<option value="">Pilih data</option>'+opts(db[collection].map(x=>({id:x.id,name:kind==='borrower'?x.name+' · '+x.code:x.model+' · '+x.serial})),obj.id);}else render();toast('Master data disimpan.');return;}if(form.id==='city-form'){const aliases=v.aliases.split(',').map(x=>x.trim()).filter(Boolean),id=form.dataset.id;if(!v.name.trim()||!v.province.trim()){$('#city-error').textContent='Nama kota dan provinsi wajib diisi.';return;}const labels=[norm(v.name),...aliases.map(norm)];if(db.cities.some(c=>c.id!==id&&[c.name,...c.aliases].some(n=>labels.includes(norm(n))))){$('#city-error').textContent='Nama/alias sudah dipakai kota lain. Gunakan alias yang tidak ambigu.';return;}let c=get('cities',id);if(!c){c={id:uid()};db.cities.push(c);}Object.assign(c,{name:v.name.trim(),province:v.province.trim(),aliases,active:v.active==='Aktif'});persist();$('#modal').close();render();toast('Master kota disimpan.');return;}if(form.id==='user-form'){if(!v.name.trim()||db.users.some(u=>norm(u.username)===norm(v.username))){$('#user-error').textContent='Nama wajib diisi dan username harus unik.';return;}db.users.push({...v,id:uid(),active:true});persist();$('#modal').close();render();toast('User ditambahkan.');}});
window.addEventListener('hashchange',()=>{filters={};page=1;$('#modal').close();render();window.scrollTo(0,0);});
const mobileFilterViewport = window.matchMedia('(max-width: 700px)');
const mobileFilterDialog = document.createElement('dialog');
mobileFilterDialog.id = 'mobile-filter-dialog';
mobileFilterDialog.className = 'mobile-filter-dialog';
mobileFilterDialog.setAttribute('aria-labelledby', 'mobile-filter-title');
document.body.appendChild(mobileFilterDialog);
let draftFilters = null;
let mobileFilterPage = '';

function activeFilterCount() {
  return Object.values(filters).filter(value => String(value ?? '') !== '').length;
}

function filterBar(kind) {
  const count = activeFilterCount();
  return `<div class="mobile-filter-toolbar"><button class="btn" type="button" data-mobile-filter-open aria-haspopup="dialog" aria-controls="mobile-filter-dialog">${icon('search')}Filter / Cari</button><span class="mobile-filter-count" aria-live="polite" ${count ? '' : 'hidden'}>${count} filter aktif</span></div>${inlineFilterBar(kind)}`;
}

function syncFilterControls() {
  document.querySelectorAll('.content .filter-bar [data-filter]').forEach(control => {
    control.value = filters[control.dataset.filter] || '';
  });
  const indicator = $('.mobile-filter-count');
  if (indicator) {
    const count = activeFilterCount();
    indicator.textContent = count + ' filter aktif';
    indicator.hidden = !count;
  }
}

function openMobileFilters() {
  if (!mobileFilterViewport.matches || mobileFilterDialog.open) return;
  mobileFilterPage = routeNow();
  draftFilters = { ...filters };
  mobileFilterDialog.innerHTML = `<form class="mobile-filter-form"><header class="mobile-filter-header"><h2 id="mobile-filter-title">Filter Data</h2><button class="btn ghost" type="button" data-mobile-filter-close aria-label="Tutup tanpa menerapkan filter" autofocus>${icon('x')}</button></header><div class="mobile-filter-body">${inlineFilterBar(mobileFilterPage)}</div><footer class="mobile-filter-footer"><button class="btn" type="button" data-mobile-filter-reset>Reset</button><button class="btn primary" type="submit">${icon('search')}Cari</button></footer></form>`;
  mobileFilterDialog.querySelector('[data-action="reset"]').remove();
  mobileFilterDialog.querySelectorAll('[data-filter]').forEach(control => {
    const key = control.dataset.filter;
    control.dataset.draftFilter = key;
    delete control.dataset.filter;
    control.value = draftFilters[key] || '';
    const originalId = control.id;
    control.id = 'mobile-' + originalId;
    const label = mobileFilterDialog.querySelector(`label[for="${originalId}"]`);
    if (label) label.htmlFor = control.id;
  });
  document.documentElement.classList.add('mobile-filters-open');
  mobileFilterDialog.showModal();
}

document.addEventListener('click', event => {
  if (event.target.closest('[data-mobile-filter-open]')) openMobileFilters();
});
mobileFilterDialog.addEventListener('click', event => {
  if (event.target.closest('[data-mobile-filter-close]')) mobileFilterDialog.close();
  if (event.target.closest('[data-mobile-filter-reset]')) {
    draftFilters = {};
    mobileFilterDialog.querySelectorAll('[data-draft-filter]').forEach(control => {
      control.value = '';
    });
  }
});
function updateDraftFilter(event) {
  if (draftFilters && event.target.matches('[data-draft-filter]')) {
    draftFilters[event.target.dataset.draftFilter] = event.target.value;
  }
}
mobileFilterDialog.addEventListener('input', updateDraftFilter);
mobileFilterDialog.addEventListener('change', updateDraftFilter);
mobileFilterDialog.addEventListener('submit', event => {
  event.preventDefault();
  if (!draftFilters || mobileFilterPage !== routeNow()) {
    mobileFilterDialog.close();
    return;
  }
  mobileFilterDialog.querySelectorAll('[data-draft-filter]').forEach(control => {
    draftFilters[control.dataset.draftFilter] = control.value;
  });
  filters = Object.fromEntries(Object.entries(draftFilters).filter(([, value]) => value !== ''));
  page = 1;
  $('#results').innerHTML = paginated(mobileFilterPage);
  syncFilterControls();
  mobileFilterDialog.close();
});
mobileFilterDialog.addEventListener('close', () => {
  draftFilters = null;
  mobileFilterPage = '';
  mobileFilterDialog.innerHTML = '';
  document.documentElement.classList.remove('mobile-filters-open');
});
mobileFilterViewport.addEventListener('change', () => {
  if (!mobileFilterViewport.matches && mobileFilterDialog.open) mobileFilterDialog.close();
});
window.addEventListener('hashchange', () => {
  if (mobileFilterDialog.open) mobileFilterDialog.close();
});
render();
